#!/bin/sh
# Campaign 5: every tracked configuration generated by the base builder
# (6c22d3ca) and by the head builder, each in its own disposable tree copy; the
# out/ trees are compared, and both trees must stay clean after generation.
# Usage: c5_byte_identity.sh <base tree> <head tree> <receipt dir>
B=$1; H=$2; R=$3; mkdir -p "$R"
O=$R/../../scratch/c5_out; rm -rf "$O"; mkdir -p "$O"
gen() { side=$1; T=$2
  (cd "$T" && for c in $(git ls-files 'configs/endstation_*.yaml'); do
     python3 sw/builder/endstation_builder.py -o "$O/$side" "$c" > "$O/$side.$(basename $c .yaml).log" 2>&1
     echo "$c rc=$?" >> "$O/$side.rc"
   done
   echo "$side $(git rev-parse HEAD)" > "$O/$side.head"
   git status --porcelain > "$O/$side.status")
}
gen base "$B" & gen head "$H" & wait
(cd "$O/base" && find . -type f | sort | xargs sha256sum) > "$R/c5_base.sha256"
(cd "$O/head" && find . -type f | sort | xargs sha256sum) > "$R/c5_head.sha256"
diff -r "$O/base" "$O/head" > "$R/c5_diff.txt" 2>&1; echo "diff_r_rc=$?" > "$R/c5_summary.txt"
cmp "$R/c5_base.sha256" "$R/c5_head.sha256" >> "$R/c5_summary.txt" 2>&1; echo "sha_list_cmp_rc=$?" >> "$R/c5_summary.txt"
echo "files=$(wc -l < "$R/c5_head.sha256")" >> "$R/c5_summary.txt"
cat "$O/base.head" "$O/head.head" "$O/base.rc" "$O/head.rc" >> "$R/c5_summary.txt"
echo "--- base tree status after generation" >> "$R/c5_summary.txt"; cat "$O/base.status" >> "$R/c5_summary.txt"
echo "--- head tree status after generation" >> "$R/c5_summary.txt"; cat "$O/head.status" >> "$R/c5_summary.txt"
echo done > "$R/c5.done"
